'use client';

import Link from 'next/link';
import { FormEvent, useEffect, useState } from 'react';
import { api } from '@/lib/api';
import { PortfolioCard, type PortfolioCardData } from '@/components/portfolio-card';
import { StatePanel } from '@/components/state-panel';

type Community = { slug: string; name: string; parent: { name: string } | null };
export default function PortfolioManagePage() {
  const [items, setItems] = useState<PortfolioCardData[]>([]); const [communities, setCommunities] = useState<Community[]>([]); const [open, setOpen] = useState(false); const [error, setError] = useState(''); const [message, setMessage] = useState('');
  const load = () => Promise.all([api<PortfolioCardData[]>('/portfolio/me'), api<Community[]>('/communities')]).then(([rows, communityRows]) => { setItems(rows); setCommunities(communityRows); setError(''); }).catch((cause) => setError(cause.message));
  useEffect(() => { void load(); }, []);
  async function create(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); setError(''); setMessage(''); const links = String(form.get('links') || '').split('\n').map((item) => item.trim()).filter(Boolean); try { await api('/portfolio', { method: 'POST', body: JSON.stringify({ kind: form.get('kind'), status: form.get('status'), title: form.get('title'), summary: form.get('summary'), description: form.get('description'), communitySlug: form.get('communitySlug') || undefined, publicationSlug: form.get('publicationSlug') || undefined, coverUrl: form.get('coverUrl') || undefined, lookingForTeam: form.get('lookingForTeam') === 'on', priceText: form.get('priceText') || undefined, contactNote: form.get('contactNote') || undefined, links }) }); setMessage('Карточка добавлена в портфолио.'); setOpen(false); event.currentTarget.reset(); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : 'Не удалось сохранить карточку'); } }
  async function archive(id: string) { try { await api(`/portfolio/${id}`, { method: 'DELETE' }); setMessage('Карточка перенесена в архив.'); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : 'Не удалось архивировать карточку'); } }
  return <div className="portfolio-manage"><section className="section-hero compact-hero"><div><span className="eyebrow">Мой профиль работы</span><h1>Проекты и услуги</h1><p>Карточка дополняет постоянную тему, но не заменяет её. Отзывы остаются доступны только после подтверждённого взаимодействия.</p></div><button type="button" className="button" onClick={() => setOpen((value) => !value)}>{open ? 'Закрыть форму' : 'Добавить'}</button></section><div className="directory-shortcuts"><Link href="/projects">Каталог проектов</Link><Link href="/services">Каталог услуг</Link><Link href="/interactions">Взаимодействия и отзывы</Link></div>{message && <div className="success-box">{message}</div>}{error && <div className="error-box">{error}</div>}{open && <section className="card portfolio-form"><h2>Новая карточка</h2><form onSubmit={create}><div className="form-grid-two"><label>Формат<select name="kind" defaultValue="PROJECT"><option value="PROJECT">Проект</option><option value="SERVICE">Услуга</option></select></label><label>Состояние<select name="status" defaultValue="ACTIVE"><option value="DRAFT">Черновик</option><option value="ACTIVE">Активно</option><option value="PAUSED">На паузе</option><option value="COMPLETED">Завершено</option></select></label></div><label>Название<input name="title" minLength={4} maxLength={120} required/></label><label>Короткое описание<textarea name="summary" minLength={20} maxLength={280} required/></label><label>Подробности<textarea name="description" minLength={40} maxLength={8000} required/></label><label>Сообщество<select name="communitySlug" defaultValue=""><option value="">Без привязки</option>{communities.map((item) => <option key={item.slug} value={item.slug}>{item.parent ? `${item.parent.name} → ` : ''}{item.name}</option>)}</select></label><label>Связанная публикация<input name="publicationSlug" placeholder="slug своей постоянной темы"/></label><label>Обложка HTTPS — необязательно<input name="coverUrl" type="url" placeholder="https://..."/></label><div className="form-grid-two"><label>Стоимость или формат работы<input name="priceText" maxLength={120} placeholder="Например, по договорённости"/></label><label>Как связаться<input name="contactNote" maxLength={500} placeholder="Написать в личные сообщения FORRUM"/></label></div><label>Ссылки — каждая с новой строки<textarea name="links" placeholder={'https://example.com\nhttps://t.me/example'}/></label><label className="form-check"><input className="form-check-input" type="checkbox" name="lookingForTeam"/><span className="form-check-label">Ищу людей в команду</span></label><button className="button">Сохранить</button></form></section>}<section className="portfolio-grid manage-grid">{items.map((item) => <div className="managed-portfolio-item" key={item.id}><PortfolioCard item={item}/><div className="managed-actions"><Link className="button secondary small" href={`/portfolio/${item.id}`}>Открыть</Link>{item.status !== 'ARCHIVED' && <button type="button" className="button ghost small" onClick={() => archive(item.id)}>В архив</button>}<span>{item.status === 'DRAFT' ? 'Черновик' : item.status === 'PAUSED' ? 'На паузе' : item.status === 'COMPLETED' ? 'Завершено' : item.status === 'ARCHIVED' ? 'Архив' : 'Активно'}</span></div></div>)}{!items.length && !open && <StatePanel title="Портфолио пока пусто" action={<button type="button" className="button small" onClick={() => setOpen(true)}>Добавить первую карточку</button>}><p>Начните с одного проекта или одной услуги, которую действительно готовы показать.</p></StatePanel>}</section></div>;
}
